#include <iostream>
using namespace std;

const double PRIX_SAC = 12.5;

int main()
{
    int nbSacs = 3;
    double prixTotal = nbSacs * PRIX_SAC; // prix avant taxes
    cout << prixTotal << '\n';
    return 0;
}
